  "claims": [
    {
      "claim": "All transferable L1 contexts report human absolute/extent oral bioavailability well above 20%: lamivudine 68.6–87% (C06, C24), zalcitabine 80% (C19), saccharin 84–88% (C10, C16), rolipram 73% (C07), ondansetron 50–65% (C01), milvexian 54–~100% (C05, C09, C22), fenspiride 90% (C03), bromazepam 86% (C11), and apixaban ~50% (C02).",
      "card_ids": ["C01","C02","C03","C05","C06","C07","C09","C10","C11","C16","C19","C22","C24"]
    },
    {
      "claim": "L2 records add further high-F measurements: lamivudine 93±15% and 86±17% (C30, C31), milvexian 105% (C29), apixaban 34–88% and dog 88% (C26, C36), and zalcitabine mouse 30% (C34), all at or above the threshold.",
      "card_ids": ["C26","C29","C30","C31","C34","C36"]
    },
    {
      "claim": "The only sub-20% values are species-specific rolipram results (rabbit 3–4%, rhesus monkey <0.1%, C27, C35) and relative oral-vs-rectal bromazepam comparisons (C32, C37); they do not overturn the human absolute F values and are not transferable affirmative evidence for low F in the query.",
      "card_ids": ["C27","C32","C35","C37"]
    },
    {
      "claim": "L3 oral AUC/Cmax records (C38–C49) concern estrone, tegafur, nevirapine, and a lidocaine analog; they report Cmax/Tmax or relative exposure without IV comparators, and several are in fed or modified-release conditions, so they provide no query-specific absolute F evidence.",
      "card_ids": ["C38","C39","C40","C41","C42","C43","C44","C45","C46","C47","C48","C49"]
    },
    {
      "claim": "The query's physicochemical profile (MW 259, logD 0.03, TPSA 92.5, neutral at pH 7.4, one rotatable bond, favorable solubility/dissolution) is consistent with the polar, low-logP high-F contexts such as lamivudine and zalcitabine; low logP alone is not affirmative evidence for F < 20%.",
      "card_ids": ["C06","C10","C19"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C38","C39","C40","C41","C42","C43","C44","C45","C46","C47","C48","C49"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule in humans or animals.",
    "No IV comparator or matched oral/IV exposure data for the query.",
    "No fasted-state pharmacokinetic or formulation-specific data for the query.",
    "No direct data on intestinal permeability, efflux transport, or first-pass metabolism for the query.",
    "L3 oral AUC/Cmax records are for unrelated molecules and are exposure-only; they do not provide query-specific F.",
    "Cross-species extrapolation is uncertain, as illustrated by rolipram's low rabbit/monkey F despite high human F (C27, C35)."
  ],
  "decision_summary": "Predicted high because all transferable L1/L2 contexts report F at or above 20% (mostly 50–90%) and the query's small polar neutral profile is consistent with those high-F drugs; L3 exposure records are for unrelated molecules and do not change the decision. Confidence remains moderate because no direct query-specific F data exist."
}

